{"path":"game/main.gd","content":"extends Node2D
class_name Main

const TILE_SIZE := 32
const GRID_W := 15
const GRID_H := 15

@onready var maze: Maze = null
@onready var ui: UI = null
@onready var mouse_node: Mouse = null
@onready var cats: Array = []

var score:int = 0
var lives:int = 3
var game_state:String = "playing"
var start_mouse_tile = Vector2(1,7)
var start_cat_tiles = [Vector2(13,7), Vector2(7,13)]
var initial_maze = null # optional Array passed by level editor

func _ready() -> void:
    # Set window title
    if OS.has_method("set_window_title"):
        OS.set_window_title("Crumb Chase")
    else:
        OS.window_title = "Crumb Chase"

    _setup_input()
    _start_game()

func _setup_input() -> void:
    var m = InputMap
    # Add arrow actions and restart/quit
    for name,key in [["turn_up", KEY_UP],["turn_down", KEY_DOWN],["turn_left", KEY_LEFT],["turn_right", KEY_RIGHT]]:
        if not m.has_action(name):
            m.add_action(name)
        var ev = InputEventKey.new()
        ev.physical_keycode = key
        m.action_add_event(name, ev)
    if not m.has_action("restart"):
        m.add_action("restart")
    var evr = InputEventKey.new(); evr.physical_keycode = KEY_R; m.action_add_event("restart", evr)
    if not m.has_action("quit"):
        m.add_action("quit")
    var evq = InputEventKey.new(); evq.physical_keycode = KEY_ESCAPE; m.action_add_event("quit", evq)

func _start_game() -> void:
    # Clean scene
    for c in get_children():
        c.queue_free()
    score = 0
    lives = 3
    game_state = "playing"

    # Create Maze
    var MazeScript = preload("res://game/maze.gd")
    maze = MazeScript.new()
    add_child(maze)
    maze.position = Vector2((800 - GRID_W * TILE_SIZE)/2, (600 - GRID_H * TILE_SIZE)/2)
    if initial_maze != null:
        maze.set_grid(initial_maze)

    # Create UI
    var UIScript = preload("res://game/ui.gd")
    ui = UIScript.new()
    add_child(ui)
    ui.update(score, lives)

    # Create Mouse
    var MouseScript = preload("res://game/mouse.gd")
    mouse_node = MouseScript.new()
    add_child(mouse_node)
    mouse_node.setup(maze, start_mouse_tile)
    mouse_node.connect("ate_crumb", Callable(self, "_on_mouse_ate_crumb"))
    mouse_node.connect("caught", Callable(self, "_on_mouse_caught"))

    # Create Cats
    var CatScript = preload("res://game/cat.gd")
    cats = []
    for t in start_cat_tiles:
        var c = CatScript.new()
        add_child(c)
        c.setup(maze, t, mouse_node)
        cats.append(c)

func _process(delta: float) -> void:
    if not Engine.is_editor_hint():
        _handle_input()

func _handle_input() -> void:
    if Input.is_action_just_pressed("turn_up"):
        print("TURN UP")
        if game_state == "playing":
            mouse_node.set_intended_direction(Vector2(0, -1))
    if Input.is_action_just_pressed("turn_down"):
        print("TURN DOWN")
        if game_state == "playing":
            mouse_node.set_intended_direction(Vector2(0, 1))
    if Input.is_action_just_pressed("turn_left"):
        print("TURN LEFT")
        if game_state == "playing":
            mouse_node.set_intended_direction(Vector2(-1, 0))
    if Input.is_action_just_pressed("turn_right"):
        print("TURN RIGHT")
        if game_state == "playing":
            mouse_node.set_intended_direction(Vector2(1, 0))
    if Input.is_action_just_pressed("restart"):
        print("RESTART")
        _start_game()
    if Input.is_action_just_pressed("quit"):
        print("QUIT")
        get_tree().quit()

func _on_mouse_ate_crumb(tile: Vector2) -> void:
    score += 10
    ui.update(score, lives)
    # Check win
    if maze.count_crumbs() == 0:
        game_state = "won"
        print("WIN")
        ui.show_end("WIN", score)

func _on_mouse_caught() -> void:
    if game_state != "playing":
        return
    lives -= 1
    ui.update(score, lives)
    # animate/reset handled by mouse signal
    if lives <= 0:
        game_state = "over"
        print("GAME OVER")
        ui.show_end("GAME OVER", score)
        # Freeze cats and mouse by telling them to stop
        for c in cats:
            c.set_active(false)
        mouse_node.set_active(false)
    else:
        # temporary freeze during respawn; reset positions
        mouse_node.respawn(start_mouse_tile)
        for i in range(cats.size()):
            cats[i].respawn(start_cat_tiles[i])

# Methods used for level editor preview
func set_initial_maze(grid):
    initial_maze = grid

# Debug helpers
func get_state() -> Dictionary:
    return {"score":score, "lives":lives, "crumbs":maze.count_crumbs()}"}

{"path":"game/maze.gd","content":"extends Node2D
class_name Maze

const GRID_W := 15
const GRID_H := 15
const TILE_SIZE := 32

var grid: Array = [] # 0 open, 1 wall
var crumbs: Dictionary = {} # key "x_y" -> Crumb node

func _init() -> void:
    _create_default_grid()

func set_grid(newgrid: Array) -> void:
    grid = newgrid.duplicate()
    _refresh()

func _create_default_grid() -> void:
    grid = []
    for y in range(GRID_H):
        var row = []
        for x in range(GRID_W):
            if x == 0 or y == 0 or x == GRID_W -1 or y == GRID_H -1:
                row.append(1)
            else:
                row.append(0)
        grid.append(row)
    # Add some interior walls for a simple maze
    for x in range(2, GRID_W-2, 2):
        for y in range(2, GRID_H-2, 2):
            grid[y][x] = 1
            if randi() % 2 == 0:
                grid[y][x+1] = 1
    _refresh()

func _refresh() -> void:
    # remove children (crumbs) then redraw
    for k in crumbs.keys():
        if crumbs[k] and crumbs[k].is_inside_tree():
            crumbs[k].queue_free()
    crumbs.clear()
    update()
    _create_crumbs()

func _create_crumbs() -> void:
    var CrumbScript = preload("res://game/crumb.gd")
    for y in range(GRID_H):
        for x in range(GRID_W):
            if grid[y][x] == 0:
                var c = CrumbScript.new()
                add_child(c)
                c.tile = Vector2(x, y)
                c.position = tile_to_pos(c.tile)
                crumbs["%d_%d" % [x,y]] = c

func is_open(tile: Vector2) -> bool:
    var x = int(tile.x); var y = int(tile.y)
    if x < 0 or y < 0 or x >= GRID_W or y >= GRID_H:
        return false
    return grid[y][x] == 0

func tile_to_pos(tile: Vector2) -> Vector2:
    # return center position in local coords
    var px = tile.x * TILE_SIZE + TILE_SIZE/2
    var py = tile.y * TILE_SIZE + TILE_SIZE/2
    return Vector2(px, py)

func pos_to_tile(pos: Vector2) -> Vector2:
    return Vector2(floor(pos.x / TILE_SIZE), floor(pos.y / TILE_SIZE))

func eat_crumb(tile: Vector2) -> bool:
    var key = "%d_%d" % [int(tile.x), int(tile.y)]
    if crumbs.has(key):
        var c = crumbs[key]
        if c and c.is_inside_tree():
            c.collect()
            crumbs.erase(key)
            return true
    return false

func count_crumbs() -> int:
    return crumbs.size()

func _draw() -> void:
    # Draw floor
    draw_rect(Rect2(Vector2.ZERO, Vector2(GRID_W * TILE_SIZE, GRID_H * TILE_SIZE)), Color(0.9,0.8,0.6))
    # Draw walls
    for y in range(GRID_H):
        for x in range(GRID_W):
            if grid[y][x] == 1:
                var r = Rect2(Vector2(x * TILE_SIZE, y * TILE_SIZE), Vector2(TILE_SIZE, TILE_SIZE))
                draw_rect(r, Color(0.2,0.2,0.2))

# Editor helper to toggle walls
func toggle_wall(tile: Vector2) -> void:
    var x = int(tile.x); var y = int(tile.y)
    if x <= 0 or y <= 0 or x >= GRID_W-1 or y >= GRID_H-1:
        return
    grid[y][x] = 1 - grid[y][x]
    _refresh()

func get_grid_copy() -> Array:
    return grid.duplicate(true) # deep copy
"}

{"path":"game/cat.gd","content":"extends Node2D
class_name Cat

const TILE_SIZE := 32
const MOVE_SPEED := 4.0 # tiles per second (slower than mouse)

var maze: Maze = null
var tile := Vector2.ZERO
var target_tile := Vector2.ZERO
var moving := false
var direction := Vector2.ZERO
var progress := 0.0
var active := true
var mouse_ref: Mouse = null

func setup(_maze, start_tile: Vector2, _mouse: Mouse) -> void:
    maze = _maze
    tile = start_tile
    position = maze.tile_to_pos(tile)
    mouse_ref = _mouse
    moving = false

func set_active(a: bool) -> void:
    active = a

func _process(delta: float) -> void:
    if not active:
        return
    if not moving:
        # choose a direction: if at junction, pick neighbor minimizing distance to mouse
        var options := []
        for d in [Vector2(1,0), Vector2(-1,0), Vector2(0,1), Vector2(0,-1)]:
            if maze.is_open(tile + d):
                options.append(d)
        if options.size() == 0:
            return
        # avoid standing still: pick direction that reduces distance
        var best := options[0]
        var bestd := INF
        for o in options:
            var t = tile + o
            var dist = (t - mouse_ref.tile).length()
            if dist < bestd:
                bestd = dist
                best = o
        direction = best
        moving = true
        target_tile = tile + direction
        progress = 0.0
    else:
        var move_time := 1.0 / MOVE_SPEED
        progress += delta / move_time
        if progress > 1.0:
            tile = target_tile
            position = maze.tile_to_pos(tile)
            moving = false
            progress = 0.0
            # check catch
            if tile == mouse_ref.tile:
                # inform parent via mouse caught signal
                var parent = get_parent()
                if parent and parent.has_method("_on_mouse_caught"):
                    parent._on_mouse_caught()
        else:
            var a = maze.tile_to_pos(tile)
            var b = maze.tile_to_pos(target_tile)
            position = a.linear_interpolate(b, progress)

func respawn(start_tile: Vector2) -> void:
    tile = start_tile
    position = maze.tile_to_pos(tile)
    moving = false
    direction = Vector2.ZERO
    progress = 0.0
"}

