const GRID_W := 15
const GRID_H := 15
const TILE_SIZE := 32

var maze_script := preload("res://game/maze.gd")
var maze: Maze = null

func _ready() -> void:
    maze = maze_script.new()
    add_child(maze)
    maze.position = Vector2((800 - GRID_W * TILE_SIZE)/2, (600 - GRID_H * TILE_SIZE)/2)
    set_process_input(true)
    # Instructions
    var l = Label.new()
    add_child(l)
    l.position = Vector2(10,10)
    l.text = "Click tiles to toggle walls. Press P to preview in main scene. ESC to quit."

func _input(event):
    if event is InputEventMouseButton and event.pressed:
        var local = event.position - maze.position
        var tile = Vector2(floor(local.x / TILE_SIZE), floor(local.y / TILE_SIZE))
        maze.toggle_wall(tile)
    if event is InputEventKey and event.pressed:
        if event.physical_keycode == KEY_P:
            _preview()
        if event.physical_keycode == KEY_ESCAPE:
            get_tree().quit()

func _preview() -> void:
    # Instantiate Main and hand over grid
    var MainScript = preload("res://game/main.gd")
    var main = MainScript.new()
    add_child(main)
    main.set_initial_maze(maze.get_grid_copy())
    # Start main manually
    main._start_game()
    # Optionally remove editor elements
    queue_free()
"}

