    if layout.size() != HEIGHT:
        build_default()
        return
    walls = []
    for y in range(HEIGHT):
        var row := []
        var layrow = layout[y]
        for x in range(WIDTH):
            var is_wall = false
            if int(layrow[x]) == 1:
